88	// in the ClusterConfiguration.ComponentConfigs map.
89	func ApplyPatchesToConfig(cfg *kubeadmapi.ClusterConfiguration, patchesDir string) error {
90		kubeletCfg, ok := cfg.ComponentConfigs[componentconfigs.KubeletGroup]
91		if !ok {
92			return errors.New("no kubelet component config found")
93		}
94	
95		if err := kubeletCfg.Mutate(); err != nil {
96			return err
97		}
98	
99		kubeletBytes, err := kubeletCfg.Marshal()
100		if err != nil {
101			return err
102		}
103	
104		// Apply patches to the KubeletConfiguration. Output is discarded.
105		if len(patchesDir) != 0 {
106			kubeletBytes, err = applyKubeletConfigPatchesFunc(kubeletBytes, patchesDir, io.Discard)
107			if err != nil {
108				return errors.Wrap(err, "could not apply patches to the KubeletConfiguration")
